     */
    public Organism(boolean randomAge, Field field, Location location,
                    OrganismAttributes attributes, OrganismFactory offspringFactory) {
        this.howLongDead = 0;
        alive = true;
        removed = false;
        this.field = field;
        this.attributes = attributes;
        this.offspringFactory = offspringFactory;
