/**
 * This file is part of the Predator-Prey Simulation.
 *
 * An animal that survives by seeking nearby food.
 *
 * @version 2022.03.02
 */
public abstract class Hunter extends ForagingAnimal {

    private final HunterAttributes attributes;
    private int foodLevel;

    /**
     * Constructor for a hunter in the simulation.
     *
     * @param foodLevel The food level of this hunter.
     * @param randomAge Whether the hunter should have a random age or not.
     * @param field The field in which the hunter resides.
     * @param location The location in which the hunter spawns into.
     */
    public Hunter(HunterAttributes attributes, boolean randomAge, Field field,
                  Location location, OrganismFactory offspringFactory) {
        super(attributes, randomAge, field, location, offspringFactory);
        this.attributes = attributes;
        this.foodLevel = attributes.getInitialFoodLevel();
    }

    @Override
    public void act(List<Organism> newHunters, SimulationContext context) {
        incrementAge();
        incrementHunger();
        if(isAlive()) {
            giveBirth(newHunters);

            if (isRestingTime(context.getTimeOfDay())) {
                return;
            }

            if (diesFromDiseaseThisTurn()) {
                remove();
                return;
            }

            moveToTargetOrRemove(chooseTargetLocation());
        }
    }

    /**
     * Increase the hunter's food level by a given integer amount.
     *
     * @param foodLevel The value to increment food level by.
     */
    protected void incrementFoodLevel(int foodLevel) {
        this.foodLevel += foodLevel;
    }

    /**
     * Make this hunter more hungry. This could result in the hunter's death.
     */
    protected void incrementHunger() {
        foodLevel--;
        if (foodLevel <= 0) {
            remove();
        }
    }

    private Location chooseTargetLocation() {
        if (rand.nextDouble() <= getDiseaseSpreadProbability()) {
            return findAnimalToInfect();
        }
        return findFood();
    }

    protected boolean isRestingTime(TimeOfDay time) {
        return attributes.getRestingTime() == time;
    }

    protected double getEatingProbability() {
        return attributes.getEatingProbability();
    }

    protected Location findMatchingPrey(Predicate<Prey> matches, Function<Prey, Boolean> onMatch) {
        for (Location location : getField().adjacentLocations(getLocation())) {
            Organism organism = getField().getOrganismAt(location);
            if (organism instanceof Prey) {
                Prey prey = (Prey) organism;
                if (matches.test(prey) && Boolean.TRUE.equals(onMatch.apply(prey))) {
                    return location;
                }
            }
        }
        return null;
    }
}

import java.util.Random;

/**
 * Shared base class for animals that move by choosing between spreading
 * disease and seeking food.
 */
public abstract class ForagingAnimal extends Animal {

    private static final Random rand = Randomizer.getRandom();

    public ForagingAnimal(AnimalAttributes attributes, boolean randomAge, Field field,
                          Location location, OrganismFactory offspringFactory) {
        super(attributes, randomAge, field, location, offspringFactory);
    }

    protected final boolean diesFromDiseaseThisTurn() {
        return rand.nextDouble() <= getDeathByDiseaseProbability();
    }

    protected final Location chooseTargetLocation() {
        if (rand.nextDouble() <= getDiseaseSpreadProbability()) {
            return findAnimalToInfect();
        }
        return findFood();
    }

    protected final void moveToTargetOrRemove(Location targetLocation) {
        Location destination = resolveDestination(targetLocation);
        if (destination != null) {
            setLocation(destination);
        }
        else {
            remove();
        }
    }

    protected Location resolveDestination(Location targetLocation) {
        if (shouldUseFallbackLocation(targetLocation)) {
            return getFallbackLocation();
        }
        return targetLocation;
    }

    protected boolean shouldUseFallbackLocation(Location targetLocation) {
        return targetLocation == null;
    }

    protected Location getFallbackLocation() {
        return getField().freeAdjacentLocation(getLocation());
    }
}

import java.util.Random;
import java.util.List;

/**
 * This file is part of the Predator-Prey Simulation.
 *
 * Abstract class for a prey in the simulation.
 *
 * @version 2022.03.02
 */
public abstract class Prey extends ForagingAnimal implements Consumable {

    // define fields
    private static final double DEFAULT_ACTIVENESS = 1;
    private static final Random rand = Randomizer.getRandom();
    private int foodValue;
    private double activeness;  // denotes how likely it is for the act method to be called

    /**
     * Constructor for a Prey in the simulation.
     *
     * @param foodValue The value of food of this prey.
     * @param randomAge Whether we assign this prey a random age or not.
     * @param field The field in which this prey resides.
     * @param location The location in which this prey is spawned into.
     */
    public Prey(int initialFoodValue, AnimalAttributes attributes, boolean randomAge,
                Field field, Location location, OrganismFactory offspringFactory) {
        super(attributes, randomAge, field, location, offspringFactory);
        this.foodValue = initialFoodValue;
        this.activeness = DEFAULT_ACTIVENESS;
    }

    /**
     * Method for what the prey does, i.e. what is always run at every step.
     *
     * @param newPrey A list of all newborn prey in this simulation step.
     * @param context The current simulation context.
     */
    @Override
    public void act(List<Organism> newPrey, SimulationContext context) {
        incrementAge();
        setActiveness(getActivenessFor(context.getTimeOfDay()));

        if(isAlive()) {
            giveBirth(newPrey);

            if (diesFromDiseaseThisTurn()) {
                remove();
                return;
            }

            if (rand.nextDouble() <= getActiveness()){
                moveToTargetOrRemove(chooseTargetLocation());
            }
        } else {
            decayifDead();
        }
    }

    /**
     * Clear the prey from the simulation as it has been eaten.
     */
    @Override
    public void setEaten() {
        clearFromField();
    }

    /**
     * Getter method for this prey's food value.
     * @return The food value of the prey.
     */
    @Override
    public int getFoodValue() {
        return this.foodValue;
    }

    /**
     * Increment the food value of this prey by a specified amount.
     * @param foodValue The given amount to increase the food value by.
     */
    protected void incrementFoodValue(int foodValue) {
        this.foodValue += foodValue;
    }

    /**
     * Called when this prey eats a plant.
     *
     * @param consumable The plant to be eaten.
     * @return Whether the plant was eaten.
     */
    @Override
    public boolean eat(Consumable consumable) {
        if ((consumable.isPoisonous()) && (!isInfected())) {
            infect(this);
        }
        incrementFoodValue(consumable.getFoodValue());
        consumable.setEaten();
        return true;
    }

    /**
     * Prey can never be poisonous.
     * @return false as prey don't have this attribute.
     */
    @Override
    public boolean isPoisonous() {
        return false;
    }

    /**
     * The activeness of this prey.
     * @return A double value for the activeness of this prey
     */
    public double getActiveness() {
        return activeness;
    }

    /**
     * Setter method for the activeness of this prey.
     *
     * @param activeness A given value for activeness.
     */
    public void setActiveness(double activeness) {
        this.activeness = activeness;
    }

    /**
     * Find a nearby plant and consume it if possible.
     *
     * @return The location of the food source, or null if none was eaten.
     */
    protected Location findPlantFood() {
        Field field = getField();
        for (Location where : field.adjacentLocations(getLocation())) {
            Organism organism = field.getOrganismAt(where);
            if (organism instanceof Plant) {
                Plant plant = (Plant) organism;
                if (plant.isAlive()) {
                    plant.setDead();
                    return eat(plant) ? where : null;
                }
            }
        }
        return null;
    }

    protected double getActivenessFor(TimeOfDay time) {
        return DEFAULT_ACTIVENESS;
    }

    @Override
    protected boolean shouldUseFallbackLocation(Location targetLocation) {
        return targetLocation == null || getFoodValue() > 10;
    }
}

